head.script:
            let dashboardData = {
    modules: [],
    tenants: [],
    serverStats: null,
    loadedCount: 0,
    totalLoadCount: 3
};

scwin.onpageload = function () {
    scwin.initializeDashboard();
    scwin.loadAllData();
};

scwin.initializeDashboard = function () {
    scwin.showLoadingState(true);
    scwin.resetDashboardUI();
};

scwin.loadAllData = function () {

    dashboardData.loadedCount = 0;

    setTimeout(() => {
        $p.executeSubmission("sbm_selectTenantList");
    }, 100);

    setTimeout(() => {
        $p.executeSubmission("sbm_selectModuleList");
    }, 300);

    setTimeout(() => {
        $p.executeSubmission("sbm_serverStats");
    }, 500);
};

scwin.getApiToken = function () {
    return sessionStorage.getItem('accessToken');
};

scwin.sbm_tenantList_submitdone = function (e) {

    try {
        const responseData = e.responseJSON;
        if (responseData && responseData.elData && responseData.elData.tenantVoList) {
            dashboardData.tenants = responseData.elData.tenantVoList;

            // 테넌트 통계 계산
            const tenantStats = scwin.calculateTenantStats(dashboardData.tenants);
            scwin.updateTenantUI(tenantStats);

        } else {
        }
    } catch (error) {
    }

    scwin.onDataLoaded();
};

scwin.sbm_tenantList_submiterror = function (e) {
    scwin.onDataLoaded();
};

scwin.sbm_moduleList_submitdone = function (e) {
    try {
        const responseData = e.responseJSON;
        if (responseData && responseData.moduleVoList) {
            dashboardData.modules = responseData.moduleVoList;

            const moduleStats = scwin.calculateModuleStats(dashboardData.modules);
            scwin.updateModuleUI(moduleStats);

            scwin.updateHighPriceModules(dashboardData.modules);

        } else {
        }
    } catch (error) {
    }

    scwin.onDataLoaded();
};

scwin.sbm_moduleList_submiterror = function (e) {
    scwin.onDataLoaded();
};

scwin.sbm_serverStats_submitdone = function (e) {

    try {
        const responseData = e.responseJSON || JSON.parse(e.responseText);
        if (responseData && responseData.summary) {
            dashboardData.serverStats = responseData;

            scwin.updateServerStatsUI(responseData);

        } else {
            scwin.updateServerStatsUI(null);
        }
    } catch (error) {
        scwin.updateServerStatsUI(null);
    }

    scwin.onDataLoaded();
};

scwin.sbm_serverStats_submiterror = function (e) {
    scwin.updateServerStatsUI(null);
    scwin.onDataLoaded();
};

scwin.onDataLoaded = function () {
    dashboardData.loadedCount++;

    if (dashboardData.loadedCount >= dashboardData.totalLoadCount) {
        scwin.showLoadingState(false);
        scwin.updateRecentActivity(); 
    }
};

scwin.calculateTenantStats = function (tenants) {
    const activeTenants = tenants.filter(t => {
        const status = String(t.isActive || t.is_active).trim();
        return status === "1" || status === "Y" || status === "true";
    }).length;

    const inactiveTenants = tenants.length - activeTenants;

    return {
        total: tenants.length,
        active: activeTenants,
        inactive: inactiveTenants
    };
};

scwin.calculateModuleStats = function (modules) {
    const freeModules = modules.filter(m => parseFloat(m.price || 0) === 0).length;
    const paidModules = modules.length - freeModules;

    const paidModulesForAvg = modules.filter(m => parseFloat(m.price || 0) > 0);
    const totalRevenue = paidModulesForAvg.reduce((sum, m) => sum + parseFloat(m.price || 0), 0);
    const avgPrice = paidModulesForAvg.length > 0 ? totalRevenue / paidModulesForAvg.length : 0;
    const highPriceModules = modules.filter(m => parseFloat(m.price || 0) > 100000).length;

    return {
        total: modules.length,
        free: freeModules,
        paid: paidModules,
        avgPrice: Math.round(avgPrice),
        totalRevenue: Math.round(totalRevenue),
        highPrice: highPriceModules
    };
};

scwin.updateTenantUI = function (stats) {
    try {
        const totalTenantsComp = $p.getComponentById("txt_totalTenants");
        const activeTenantsComp = $p.getComponentById("txt_activeTenants");

        if (totalTenantsComp) totalTenantsComp.setValue(stats.total);
        if (activeTenantsComp) activeTenantsComp.setValue(stats.active);


    } catch (error) {
    }
};

scwin.updateModuleUI = function (stats) {
    try {
        const totalModulesComp = $p.getComponentById("txt_totalModules");
        const freeModulesComp = $p.getComponentById("txt_freeModules");
        const avgPriceComp = $p.getComponentById("txt_avgPrice");

        if (totalModulesComp) totalModulesComp.setValue(stats.total);
        if (freeModulesComp) freeModulesComp.setValue(stats.free);
        if (avgPriceComp) avgPriceComp.setValue(`₩${stats.avgPrice.toLocaleString()}`);


    } catch (error) {
    }
};

scwin.updateServerStatsUI = function (serverData) {
    try {
        const connectedUsersComp = $p.getComponentById("txt_connectedUsers");
        const activeSessionsComp = $p.getComponentById("txt_activeSessions");
        const serverStatusComp = $p.getComponentById("txt_serverStatus");

        if (serverData && serverData.summary) {
            const connectedUsers = serverData.summary.totalConnectedPeers || 0;
            const activeSessions = serverData.summary.activeRoomCount || 0;

            if (connectedUsersComp) connectedUsersComp.setValue(connectedUsers);
            if (activeSessionsComp) activeSessionsComp.setValue(activeSessions);
            if (serverStatusComp) {
                serverStatusComp.setValue("정상");
                serverStatusComp.removeClass("status-error");
                serverStatusComp.addClass("status-badge");
            }

        } else {
            if (connectedUsersComp) connectedUsersComp.setValue(0);
            if (activeSessionsComp) activeSessionsComp.setValue(0);
            if (serverStatusComp) {
                serverStatusComp.setValue("오류");
                serverStatusComp.removeClass("status-badge");
                serverStatusComp.addClass("status-error");
            }
        }
    } catch (error) {
    }
};

scwin.updateHighPriceModules = function(modules) {
    const container = document.getElementById('popular_modules_container');
    if (!container) return;

    try {
        const sortedModules = [...modules]
            .sort((a, b) => parseFloat(b.price || 0) - parseFloat(a.price || 0))
            .slice(0, 3);

        if (sortedModules.length === 0) {
            container.innerHTML = '<div class="realtime-item-empty">표시할 모듈이 없습니다.</div>';
            return;
        }

        let html = '';
        sortedModules.forEach(module => {
            const price = parseFloat(module.price || 0);
            const priceStatus = price === 0 ? 'status-free' : 'status-paid';
            const priceText = price === 0 ? '무료' : `₩${price.toLocaleString()}`;

            html += `
                <div class="realtime-item">
                    <div class="module-icon-latest">${(module.name || 'M').charAt(0)}</div>
                    <div class="item-info">
                        <div class="item-title">${module.name || '이름 없음'}</div>
                        <div class="item-desc">${module.description || '설명 없음'}</div>
                    </div>
                    <div class="item-status ${priceStatus}">${priceText}</div>
                </div>
            `;
        });
        container.innerHTML = html;
    } catch (error) {
        container.innerHTML = '<div class="realtime-item-empty">오류가 발생했습니다.</div>';
    }
};

scwin.updateRecentActivity = function() {
    const container = document.getElementById('recent_activity_container');
    if (!container) return;

    try {
        const recentTenants = [...dashboardData.tenants]
            .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0))
            .slice(0, 5);

        if (recentTenants.length === 0) {
            container.innerHTML = '<div class="realtime-item-empty">최근 활동이 없습니다.</div>';
            return;
        }

        let html = '';
        recentTenants.forEach(tenant => {
            const isActive = String(tenant.isActive || tenant.is_active).trim() === "1" || String(tenant.isActive || tenant.is_active).trim() === "true";
            const statusClass = isActive ? 'status-active' : 'status-inactive';
            const statusText = isActive ? '활성' : '비활성';

            html += `
                <div class="realtime-item">
                    <div class="item-info">
                        <div class="item-title">${tenant.name || '이름 없는 테넌트'}</div>
                        <div class="item-desc">사용자 ${tenant.user_count || 0}명 • 모듈 ${tenant.module_count || 0}개</div>
                    </div>
                    <div class="item-status ${statusClass}">${statusText}</div>
                </div>
            `;
        });
        container.innerHTML = html;
    } catch (error) {
        container.innerHTML = '<div class="realtime-item-empty">오류가 발생했습니다.</div>';
    }
};

scwin.showLoadingState = function (isLoading) {
    try {
        const loadingElements = document.querySelectorAll('.loading-indicator');
        loadingElements.forEach(element => {
            element.style.display = isLoading ? 'block' : 'none';
        });

        const statCards = document.querySelectorAll('.stat-card');
        statCards.forEach(card => {
            if (isLoading) {
                card.classList.add('loading');
            } else {
                card.classList.remove('loading');
            }
        });
    } catch (error) {
    }
};

scwin.resetDashboardUI = function () {
    try {
        const components = [
            'txt_totalModules', 'txt_activeTenants', 'txt_connectedUsers',
            'txt_activeSessions', 'txt_serverStatus', 'txt_freeModules',
            'txt_avgPrice', 'txt_totalTenants'
        ];

        components.forEach(id => {
            const comp = $p.getComponentById(id);
            if (comp) {
                comp.setValue('-');
            }
        });

        const popularModulesContainer = document.getElementById('popular_modules_container');
        if (popularModulesContainer) {
            popularModulesContainer.innerHTML = '<div class="realtime-item-empty">모듈 데이터를 불러오는 중...</div>';
        }
        const recentActivityContainer = document.getElementById('recent_activity_container');
        if (recentActivityContainer) {
            recentActivityContainer.innerHTML = '<div class="realtime-item-empty">활동 데이터를 불러오는 중...</div>';
        }

    } catch (error) {
    }
};

scwin.refreshDashboard = function () {
    scwin.initializeDashboard();
    scwin.loadAllData();
};

scwin.btn_home_onclick = function () {
    scwin.refreshDashboard();
};

scwin.btn_tenant_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile/mobile_dev_tenant.xml";
};

scwin.btn_module_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile/mobile_dev_module.xml";
};

scwin.btn_stats_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile/mobile_dev_server_info.xml";
};
